    const wideF = followLine(follow('rotate', 1), handPoses('d', { k: { setup: rot(0), frames: [rot(50)] } }), handPoses('r', { k: { setup: rot(0), frames: [rot(0)] } }), handPoses('f', { k: { setup: rot(0), frames: [rot(100)] } }));
