    const stretch = (within: number, rest = [square], frames = geomFrames): RequirementLine => stretchRequirementLine({ name: 'S', kind: 'stretch', animation: 'a', slot: 's', attachment: 'm', within_ratio: within }, rest, frames, sPoses);
