    const cRig = JSON.parse(readFileSync(join(composed, 'rig.json'), 'utf8')) as Record<string, unknown>;
    const cMotion = JSON.parse(readFileSync(join(composed, 'motion.json'), 'utf8')) as Record<string, unknown>;
